SELECT s.id, s.category_id, s.spec_name, s.spec_value, s.spec_unit, s.status, s.user_id, s.create_by, s.update_by, s.create_time, s.update_time, c.category_name FROM shop_product_spec s LEFT JOIN shop_category c ON c.id = s.category_id AND c.is_deleted = 0
s.is_deleted = 0
AND s.category_id = #{q.categoryId}
AND s.status = #{q.status}
AND (s.spec_name LIKE CONCAT('%', #{q.keyword}, '%') OR s.spec_value LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY s.category_id ASC, s.status DESC, s.id DESC
